    "q": "เชื้อ Listeria monocytogenes และ เชื้อ Staphylococcus aureus ที่ปนเปื้อนในเนื้อสัตว์หรือผลิตภัณฑ์จากเนื้อสัตว์จะก่อให้เกิดโรคในผู้บริโภคในลักษณะใด",
