    "q": "เชื้อแบคทีเรียชนิดใดที่เป็นสาเหตุสำคัญที่ทำให้เกิดการเน่าเสียที่บริเวณผิวของเนื้อสัตว์ (surface spoilage) และทำให้เกิดการเน่าเสียของเนื้อสัตว์ส่วนที่อยู่ลึกเข้าไปข้างใน (deep spoilage)",
