    "q": "ทดสอบสาร A เทียบกับ phenol กับเชื้อมาตรฐาน ได้ผลดังนี้ phenol ที่ความเจือจาง 1/90 ฆ่าเชื้อได้หมดตั้งแต่ 5 นาที (000) และที่ 1/100 ฆ่าเชื้อได้หมดเมื่อ 15 นาที (++0) ส่วนสาร A ที่ความเจือจาง 1/300 ฆ่าเชื้อได้หมดตั้งแต่ 5 นาที (000) และที่ 1/350 ฆ่าเชื้อได้หมดเมื่อ 15 นาที (++0) จงคำนวณค่า phenol coefficient (P.C.) ของสาร A",
