    "explain": "Deep spoilage (มักเกิดลึกใกล้กระดูก) มีสาเหตุหลักจาก Clostridium และ Enterococcus โดย Clostridium ที่เกี่ยวข้องคือ C. sporogenes, C. histolyticum และ C. butyricum ซึ่งไม่มีในรายการคำตอบ ตัวเลือกในรายการที่ตรงกับสาเหตุของ deep spoilage จึงเป็น Enterococcus spp. ส่วน C. botulinum ไม่อยู่ในรายชื่อเชื้อที่ทำให้ deep spoilage\n\nยีสต์ที่ทำให้เนื้อและผลิตภัณฑ์เนื้อเน่าเสียคือ Candida, Torulopsis และ Rhodotorula โดยเฉพาะ Candida zeylanoides และ Candida lipolytica ทำให้เกิดเมือกและสี กลิ่น รสเปลี่ยน Candida albicans ไม่อยู่ในกลุ่มนี้\n\nSerratia liquefaciens (ชื่อเดิม Enterobacter liquefaciens) ทำให้ vacuum packaged DFD meat (pH มากกว่า 6) เน่าเสียและมีกลิ่น และเจริญบนเนื้อ pH ปกติได้แต่ช้ากว่า ส่วน Shewanella putrefaciens (Alteromonas putrefaciens) ทำให้ DFD meat ที่บรรจุสุญญากาศเน่าและเกิดสีเขียว แต่เจริญบนเนื้อที่มี pH ปกติไม่ได้ (ไม่เจริญที่ pH 6 หรือต่ำกว่า)\n\nในการแช่เย็นแบบมีอากาศ Pseudomonas เป็นเชื้อเด่นและเป็นสาเหตุสำคัญที่สุดของการเน่าเสียแบบใช้อากาศ ใช้กลูโคสก่อนแล้วจึงย่อยกรดอะมิโนเกิดสารมีกลิ่น เช่น sulfide และ ester\n\nSporotrichum และ Chrysosporium ทำให้เกิด white spot ส่วน Thamnidium, Mucor และ Rhizopus ทำให้เกิดหย่อมสีขาว (white patches) และ Cladosporium ทำให้เกิด black spot",
    "source": "Microbiology of meat หน้า 16, 19, 25-26, 34-35, 43, 51",
    "verified": "บันทึกข้อสอบกลางภาค Meat แบบออนไลน์ (ไม่ระบุรุ่น) ในชุดไฟล์ Vet 84 หน้า 2-6 ข้อจับคู่ 1-5; บันทึกหลังสอบปลายภาค Meat Hygiene ปี 2018 ในสรุปเขียนมือของชุดไฟล์ Vet 84 หน้า 2 ส่วนจับคู่ (deep spoilage, ยีสต์, เชื้อใน vacuum และใน DFD, เชื้อหลักที่ทำให้เน่าเสีย, ราที่ทำให้เกิดจุดขาว); บันทึกหลังสอบปลายภาค Meat hygiene final ฉบับพิมพ์ ในสรุปเขียนมือของชุดไฟล์ Vet 84 หน้า 2 ส่วนเติมคำ (เชื้อที่ทำให้เกิด deep spoilage, ราที่ทำให้เกิดจุดดำจุดขาว) (สำเนาหน้า 6)",
