    "explain": "Acinetobacter และ Moraxella เป็นแบคทีเรียแกรมลบที่ต้องใช้อากาศ เจริญได้ดีที่อุณหภูมิต่ำ ย่อยกรดอะมิโนแต่ไม่สร้างสารมีกลิ่น จึงเป็นเชื้อที่มี low spoilage potential\n\nCladosporium (Cladosporium herbarum) เป็นสาเหตุสำคัญของ black spot บนผิวเนื้อที่แห้งและเป็นกรด\n\nLactobacillus เจริญดีในสภาวะไม่มีอากาศ อุณหภูมิต่ำ aw ต่ำ (ตั้งแต่ 0.91) และเป็นกรด (pH 4.5 หรือต่ำกว่า) ได้ดีกว่า Brochothrix thermosphacta ทั้งสองเป็นสาเหตุหลักของการเน่าเสียของ vacuum packaged meat โดย Lactobacillus สร้างกรดไขมันระเหยได้ให้กลิ่น cheesy\n\nFreshly-slaughtered meat มีเชื้อประมาณ 10² ถึง 10⁴ CFU/g ส่วนใหญ่เป็น mesophiles ได้แก่ coliforms, enterococci, micrococci, Clostridium perfringens และ Staphylococcus aureus Enterococcus จึงเป็นเพียงส่วนหนึ่งของกลุ่ม คำตอบที่ครอบคลุมคือ Mesophiles\n\nมาตรฐานของกรมปศุสัตว์และกรมวิทยาศาสตร์การแพทย์กำหนดให้ Salmonella spp. ต้องไม่พบใน 25 g ทั้งในเนื้อดิบ แช่เย็น แช่แข็ง และเนื้อปรุงสุก ส่วน Campylobacter jejuni และ Listeria monocytogenes ไม่มีเกณฑ์ในเนื้อดิบตามมาตรฐานกรมปศุสัตว์ จึงไม่ใช่เชื้อที่ห้ามพบในทุกมาตรฐาน",
    "source": "Microbiology of meat หน้า 20-22, 35, 39, 60-65",
    "verified": "บันทึกข้อสอบกลางภาค Meat แบบออนไลน์ (ไม่ระบุรุ่น) ในชุดไฟล์ Vet 84 หน้า 7-11 ข้อจับคู่ 6-10; บันทึกหลังสอบปลายภาค Meat Hygiene ปี 2018 ในสรุปเขียนมือของชุดไฟล์ Vet 84 หน้า 2 ส่วนจับคู่ (low spoilage potential, ราที่ทำให้เกิดจุดดำ, เชื้อใน vacuum, เชื้อใน freshly-slaughtered meat); บันทึกหลังสอบปลายภาค Meat hygiene final ฉบับพิมพ์ ในสรุปเขียนมือของชุดไฟล์ Vet 84 หน้า 2 ส่วนเติมคำ (ราที่ทำให้เกิดจุดดำจุดขาว) (สำเนาหน้า 6)",
