    "model_answer": "Growth curve ของแบคทีเรียมี 4 ระยะ คือ lag phase (ปรับตัว ยังไม่เพิ่มจำนวน), log phase (เพิ่มจำนวนเร็วที่สุด), stationary phase (จำนวนคงที่) และ death phase (เชื้อตาย) การควบคุมเชื้อในเนื้อสัตว์อาศัยการทำให้เชื้อเริ่มต้นน้อยที่สุดและยืด lag phase ให้นานที่สุด เพื่อชะลอไม่ให้เชื้อเข้าสู่ log phase ซึ่งจำนวนเชื้อเพิ่มจนเนื้อเริ่มมีกลิ่น (ประมาณ 10⁶ ถึง 10⁷ ต่อกรัม) และเน่าเสีย วิธีที่ใช้คือป้องกันการปนเปื้อนตั้งแต่ต้น ลดอุณหภูมิเนื้อและซากลงถึง 4°C ในเวลาสั้น และเปลี่ยนสภาวะการเก็บให้ไม่เหมาะกับเชื้อ เช่น บรรจุแบบสุญญากาศ หรือเติม CO2 หรือ N2O ในบรรจุภัณฑ์ ผลคือเนื้อปลอดภัยและเก็บได้นานขึ้น",
