    "q": "ซากส่วนใหญ่จะมีอุณหภูมิประมาณ 30-39°C หลังการฆ่า ควรได้รับการลดอุณหภูมิทันที โดยให้อุณหภูมิภายในต่ำกว่า 5°C ภายใน 24 ชั่วโมงหลังการฆ่า",
