    "explain": "การแช่เย็นซากต้องลดอุณหภูมิให้ต่ำกว่า 5°C ภายใน 8 ชั่วโมงหลังฆ่า แล้วคงไว้ที่ 0-3°C ปัจจัยที่มีผลต่ออัตราการเย็นตัว ได้แก่ อุณหภูมิซาก ไขมันที่คลุมซาก ขนาดซาก จำนวนซาก และความชื้นในห้องเย็น ส่วนที่ผิดคือ 24 ชั่วโมง อย่าสับสนกับเกณฑ์ของ มกษ. โรงฆ่าสุกรและโค ที่ให้อุณหภูมิใจกลางซากไม่เกิน 7°C ภายใน 24 ชั่วโมง ซึ่งเป็นคนละเกณฑ์",
    "source": "Storage of meat and meat products หน้า 15; MeatHyg_E2SlaugtHygDes_67_1 deck 2024 หน้า 34, 47",
