    "explain": "RN gene (Rendement Napole) ในสุกร RN- เกี่ยวกับ AMP kinase ทำให้กล้ามเนื้อมี glycogen สูง pH ต่ำ (acid meat) และ cooking yield ลดลงได้ถึง 8%\n\nยาต้านจุลชีพตกค้างเป็นอันตรายทางเคมี ต้องควบคุมตั้งแต่ฟาร์มร่วมกับสารปนเปื้อนเคมีอื่น\n\nแบคทีเรียก่อโรคและแบคทีเรียที่ทำให้เน่าเสียเป็นอันตรายทางชีวภาพ ในโรงฆ่าควบคุมด้วย HACCP และ GMP ร่วมกับการป้องกันการปนเปื้อนข้าม\n\nปัจจัยก่อนฆ่า ได้แก่ ความเครียดและลักษณะกล้ามเนื้อ พันธุกรรมและยีนหลัก อายุ เพศ อาหาร ตำแหน่งกล้ามเนื้อ การจัดการก่อนฆ่า และวิธีควบคุมสัตว์ (immobilization method)\n\nปัจจัยหลังฆ่า ได้แก่ อุณหภูมิในการเก็บซาก การแปรรูปเร็ว (accelerated processing) และการกระตุ้นซากด้วยไฟฟ้า (carcass electrical stimulation)\n\nตัวเลือกที่ไม่ได้ใช้ในชุดนี้ คือ ขนและเศษดินหินในน้ำนมดิบ (อันตรายทางกายภาพในน้ำนม ไม่ใช่ในเนื้อ) และขั้นตอนการผลิตเนื้อให้สะอาดปลอดภัย",
