    "explain": "คุณภาพเนื้อขึ้นกับปัจจัยตั้งแต่ตัวสัตว์และการจัดการในฟาร์ม (การให้อาหาร การจัดการสัตว์) การฆ่า กระบวนการหลังฆ่า จนถึงการปฏิบัติต่อซาก ตัวเลือกที่ครอบคลุมเรื่องนี้คือ สายพันธุ์สัตว์ การจัดการฟาร์ม กระบวนการฆ่า และการปฏิบัติต่อซาก\n\nลักษณะคุณภาพเนื้อถูกควบคุมด้วย quantitative trait loci (QTL) จำนวนหนึ่งที่ยังไม่ทราบแน่ชัด\n\nHalal authentication คือการรับรองว่าผลิตภัณฑ์เนื้อปราศจากเนื้อสุกรปนเปื้อน ต้องใช้วิธีตรวจที่เชื่อถือได้ รวดเร็ว ราคาไม่สูง และตรวจพบเนื้อสุกรปริมาณน้อยมากในผลิตภัณฑ์บดได้\n\nCandidate gene approach มี 5 ขั้น คือ รวบรวมประชากร วัดลักษณะปรากฏ เลือกยีนที่น่าจะเกี่ยวข้อง หา genotype ของประชากร และขั้นสุดท้ายวิเคราะห์ทางสถิติหาความสัมพันธ์ระหว่าง genotype กับ phenotype\n\nในสุกร H-FABP gene และ A-FABP (FABP4) gene สัมพันธ์กับปริมาณไขมันแทรกในกล้ามเนื้อ ส่วน calpastatin gene สัมพันธ์กับความแน่นและความนุ่มของเนื้อ",
    "source": "Use of molecular techniques for meat quality and authentication หน้า 6-9, 17-18",
    "verified": "บันทึกข้อสอบกลางภาค Meat แบบออนไลน์ (ไม่ระบุรุ่น) ในชุดไฟล์ Vet 84 หน้า 22 ข้อจับคู่ส่วน molecular ข้อ 1-5; ชุดสรุปปลายภาค Meat ของ Vet 85 หน้า 11 ส่วน molecular; บันทึกหลังสอบปลายภาค Meat Hygiene ปี 2018 ในสรุปเขียนมือของชุดไฟล์ Vet 84 หน้า 1 ส่วน storage, quality และ molecular (halal authen of raw meat)",
