    "explain": "ในไก่เน้นการสะสมไขมัน เช่น ไขมันใต้ผิวหนัง ไขมันช่องท้อง และไขมันแทรกในอกและขา โดยต้องการเพิ่ม intramuscular fat ยีนที่เกี่ยวข้อง เช่น EX-FABP และ L-FABP\n\nELISA เป็น protein-based technique ที่ใช้มากที่สุด รวดเร็วและเชื่อถือได้ แต่จำเพาะน้อยกว่าวิธีที่อาศัย PCR\n\nCandidate gene approach ทดสอบความสัมพันธ์ระหว่างการกลายพันธุ์ของยีนที่คาดว่าอยู่ในวิถีทางสรีรวิทยาของลักษณะนั้นกับความแปรผันของลักษณะปรากฏ ยีน calpain สัมพันธ์กับความนุ่มจึงศึกษาด้วยวิธีนี้ ส่วน genome scan approach ใช้หาว่ายีนใดบนโครโมโซมเกี่ยวข้องกับลักษณะ\n\nPCR ตรวจลำดับ DNA ที่พบบ่อย คือ mitochondrial 12S rRNA ใช้ตรวจเนื้อโค แกะ แพะ และสุกร ทั้งในเนื้อดิบและเนื้อผ่านความร้อน\n\nPCR (DNA-based) ตรวจพบเนื้อสุกร ม้า และลา 0.1% ในไส้กรอกสุก และใช้ระบุชนิดเนื้อสัตว์ได้ (PCR-RFLP, real-time PCR, species-specific PCR, RAPD, PCR sequencing)",
