    "explain": "ลักษณะคุณภาพเนื้อถูกควบคุมด้วย QTL หลายตำแหน่ง ยีนเดียวที่เลือกมาศึกษาใน candidate gene approach จึงอธิบายลักษณะปรากฏได้ไม่ทั้งหมด\n\nImmunochromatographic assay ใช้อนุภาคทองคำขนาดนาโน (colloidal gold) รวดเร็ว ราคาถูก ไม่ต้องใช้เครื่องมือหรือทักษะพิเศษ เหมาะคัดกรองตัวอย่างจำนวนมากก่อนยืนยันด้วยวิธีที่อาศัย DNA หรือโปรตีน\n\nFTIR spectroscopy ตรวจหาและวัดปริมาณไขมันสุกร (lard) ร่วมกับ partial least square calibration เช่น ในลูกชิ้นเนื้อโค\n\nในโค DGAT เกี่ยวกับปริมาณไขมันในกล้ามเนื้อ และ activity ของ DGAT เพิ่ม longissimus dorsi muscle ยีนอื่นในโค ได้แก่ calpastatin และ calpain (ความนุ่ม) และ myostatin (น้ำหนักเนื้อ)\n\nGenome scan approach ใช้ระบุว่ายีนหรือตำแหน่งใดบนโครโมโซมสัมพันธ์กับลักษณะคุณภาพเนื้อ แล้วใช้ fine mapping หา marker ที่อยู่ใกล้ยีนเป้าหมาย",
