    "answer": 0,
    "explain": "Phytotoxins สร้างโดยสาหร่ายเซลล์เดียวและแพลงก์ตอนพืช: domoic acid จาก diatom (Pseudo-nitzschia, ASP), brevetoxin จาก dinoflagellate Karenia brevis (NSP) และ saxitoxin จาก dinoflagellates (PSP) ข้ออื่นมีสารที่ไม่ได้มาจากสาหร่าย คือ histamine เกิดจากแบคทีเรียย่อย histidine ในปลาที่เก็บไม่เย็นพอ tetrodotoxin สร้างโดยแบคทีเรีย และ tetraodontiformes เป็นชื่ออันดับของปลาปักเป้า ไม่ใช่สารพิษ",
    "source": "MI_SP_E1.2 หน้า 47, 50, 53, 56, 58, 63",
