    "q": "สารประกอบตามธรรมชาติที่สัตว์น้ำมีมากกว่าสัตว์เลือดอุ่น ซึ่งทำให้เกิดรสชาติและกลิ่นเฉพาะตัวของอาหารที่มาจากสัตว์น้ำ คือข้อใด?",
    "options": [
      "Non-protein nitrogen compounds ได้แก่ trimethylamine oxide, urea, betaines",
      "Saturated fatty acids ได้แก่ palmitic acid, stearic acid",
      "Poly-unsaturated fatty acids ได้แก่ omega-3 fatty acids, omega-6 fatty acids",
      "Stroma proteins ได้แก่ collagen, elastin, gelatin",
      "Sarcoplasmic proteins ได้แก่ myoglobin, oxymyoglobin, haemocyanin"
    ],
    "answer": 0,
    "explain": "สารประกอบไนโตรเจนที่ไม่ใช่โปรตีน (NPN) ได้แก่ กรดอะมิโนอิสระ dipeptide nucleotide guanidine compounds TMAO urea และ betaines ระเหยได้และมีกลิ่น จึงกำหนดลักษณะทางประสาทสัมผัสและการเน่าเสียของผลิตภัณฑ์สัตว์น้ำ ส่วนกรดไขมันอิ่มตัวและไม่อิ่มตัวไม่ใช่สารที่ให้รสชาติและกลิ่นเฉพาะตัวนี้ ปลามี stroma protein (collagen) น้อยกว่าสัตว์บก และ sarcoplasmic protein เป็นโปรตีนละลายน้ำ ได้แก่ เอนไซม์และโปรตีนสี",
