      "มีขนาดเส้นผ่าศูนย์กลางของเส้นใยกล้ามเนื้อใหญ่กว่าเมื่อเทียบกับกล้ามเนื้อขาว (White muscle)",
      "มีความหนาแน่นของหลอดเลือดฝอยในกล้ามเนื้อสูงกว่าเมื่อเทียบกับกล้ามเนื้อขาว (White muscle)",
      "กระบวนการเมตาบอลิซึม (Metabolism) หลักที่พบ คือ ไกลโคไลซิส (Glycolysis)",
      "ไม่มีเส้นใยกล้ามเนื้อขาว (White muscle fiber) เป็นส่วนประกอบ"
