    "answer": 2,
    "explain": "เส้นใยกล้ามเนื้อแดง (type I และ IIA) มี capillary density สูง มี myoglobin มาก เส้นใยขนาดเล็ก และใช้ oxidative metabolism เป็นหลัก ข้อที่ว่ามี myoglobin น้อยกว่าผิดเพราะมีมากกว่า ข้อที่ว่าเส้นใยใหญ่กว่าผิดเพราะเส้นผ่าศูนย์กลางเล็กกว่า ข้อที่ว่าใช้ glycolysis เป็นหลักผิดเพราะ glycolysis เด่นในเส้นใยขาว (type IIX และ IIB) และข้อที่ว่าไม่มีเส้นใยขาวเลยผิดเพราะกล้ามเนื้อหนึ่งมัดมีเส้นใยหลายชนิดปนกัน กล้ามเนื้อแดงจึงมีเส้นใยขาวอยู่บ้าง",
