    "q": "ข้อความใดถูกต้องที่สุดเกี่ยวกับคาร์โบไฮเดรต (Carbohydrate) ในสัตว์และเนื้อสัตว์?",
    "options": [
      "ในปลาจะมีการสะสมของคาร์โบไฮเดรตในรูปของไกลโคเจน (Glycogen) ในกล้ามเนื้อมากกว่าเมื่อเทียบกับสัตว์เลี้ยงลูกด้วยนม",
      "ไกลโคเจน (Glycogen) ที่สะสมในกล้ามเนื้อสัตว์จะถูกเปลี่ยนเป็นกรดแลคติค (Lactic acid) ในระหว่างกระบวนการเปลี่ยนแปลงหลังจากสัตว์ตาย (Postmortem changes) และส่งผลให้ pH ของซากสัตว์ลดลง",
      "เนื้อสัตว์เป็นแหล่งคาร์โบไฮเดรตที่ดี โดยเฉพาะอย่างยิ่งในสัตว์น้ำทุกชนิด",
      "ในสัตว์เลี้ยงลูกด้วยนมที่อาศัยอยู่บนบกจะมีการสะสมของคาร์โบไฮเดรตในรูปของไกลโคเจน (Glycogen) ในตับมากกว่าในกล้ามเนื้อ",
      "ปริมาณของไกลโคเจน (Glycogen) ที่สะสมในกล้ามเนื้อของสัตว์น้ำมีน้อยมากจนไม่ส่งผลต่อกระบวนการเปลี่ยนแปลงหลังจากสัตว์ตาย (Postmortem changes)"
    ],
    "answer": 1,
    "explain": "ไกลโคเจนในกล้ามเนื้อถูกเปลี่ยนเป็น lactic acid หลังสัตว์ตาย ทำให้ pH ของซากลดลง ข้อที่ว่าปลาสะสมไกลโคเจนในกล้ามเนื้อมากกว่าผิดเพราะกล้ามเนื้อปลามีไกลโคเจนน้อยกว่าสัตว์เลี้ยงลูกด้วยนม ข้อที่ว่าเนื้อสัตว์เป็นแหล่งคาร์โบไฮเดรตที่ดีผิดเพราะเนื้อสดส่วนใหญ่เป็นแหล่งคาร์โบไฮเดรตที่ไม่ดี และคาร์โบไฮเดรตในสัตว์ทะเลต่ำมาก มีเพียงสัตว์ไม่มีกระดูกสันหลังบางชนิดที่สูง ข้อที่ว่าสัตว์บกสะสมไกลโคเจนในตับมากกว่าในกล้ามเนื้อไม่ถูก ร่างกายเก็บไกลโคเจนไว้ทั้งในตับ (2-8% ของน้ำหนักตับ) และในกล้ามเนื้อ ตับเข้มข้นกว่าแต่กล้ามเนื้อมีมวลมากกว่ามาก และข้อที่ว่าไกลโคเจนในสัตว์น้ำน้อยจนไม่มีผลผิดเพราะไกลโคเจนที่มีอยู่ยังเปลี่ยนเป็น lactic acid และมีผลต่อ rigor mortis และ pH หลังตายของปลา",
