      "สัตว์น้ำทุกชนิดจะมีปริมาณไขมัน (% lipid) ในเนื้อน้อยกว่าสัตว์เลือดอุ่นทั้งหมด",
      "น้ำเป็นองค์ประกอบหลักที่พบได้มากที่สุดในเนื้อของสัตว์น้ำ โดยทั้งหมดจะอยู่ในรูป free water",
