    "year": 5,
    "type": "mcq",
    "examScope": "final",
    "q": "ข้อความที่ถูกต้องที่สุดเกี่ยวกับปรากฏการณ์ขี้ปลาวาฬ (Red tide) คือข้อใด?",
    "options": [
      "ปรากฏการณ์ red tide มักทำให้เกิดการเพิ่มขึ้นของสารพิษที่ส่งผลกระทบต่อมนุษย์ โดยไม่ส่งผลกระทบใดๆ ต่อสัตว์น้ำทุกชนิด",
      "สารพิษที่ส่งผลกระทบต่อมนุษย์และเกี่ยวข้องกับการเกิด red tide มากที่สุด คือ Saxitoxin",
      "ความเป็นพิษหรือผลกระทบจากปรากฏการณ์ red tide สามารถเกิดขึ้นหลังการเกิด red tide ไปแล้วเป็นเวลานาน",
      "สามารถพบปรากฏการณ์ red tide ได้ทั่วโลก โดยพบได้เฉพาะในน้ำทะเลและน้ำกร่อย",
      "สารพิษที่เกิดขึ้นจากปรากฏการณ์ red tide สามารถถูกกำจัดได้โดยการผ่านความร้อนสูงเป็นเวลานานอย่างน้อย 5 นาที"
    ],
    "answer": 2,
    "explain": "สารพิษจากการบลูมของสาหร่ายสะสมในหอยและปลาโดยไม่ทำอันตรายต่อสัตว์ที่สะสม ไม่มีรส ไม่มีสี และทนความร้อน หอยและปลาจึงยังเป็นพิษได้หลังน้ำแดงผ่านไปแล้ว ข้อที่ว่าความเป็นพิษเกิดได้หลังน้ำแดงผ่านไปนานจึงถูกที่สุด ข้อที่ว่าไม่กระทบสัตว์น้ำผิดเพราะน้ำแดงทำให้ปลาตายจำนวนมาก ข้อที่ยก saxitoxin ผิดเพราะสารพิษที่ผูกกับน้ำแดง (Florida red tide) คือ brevetoxin จาก Karenia brevis ข้อที่ว่ากำจัดได้ด้วยความร้อนผิดเพราะสารพิษทนความร้อน ส่วนข้อที่ว่าพบได้ทั่วโลก การเกิดน้ำแดงที่ทำให้ NSP พบหลักในอ่าวเม็กซิโก ชายฝั่งแอตแลนติกตอนใต้ของสหรัฐฯ และนิวซีแลนด์ จึงไม่ใช่ข้อที่ถูกที่สุด",
