    "model_answer": "GMP ของโรงฆ่าสัตว์ปีกตาม มกษ. 9008-2549 แบ่งเป็นคอกพักสัตว์ปีก พื้นที่ผลิตส่วนไม่สะอาด และพื้นที่ผลิตส่วนสะอาด สายการผลิตเดินทางเดียวไม่ย้อนกลับ ขั้นตอนสำคัญ (1) รับสัตว์ปีก: อดอาหารอย่างน้อย 1 ชั่วโมงก่อนขนส่ง มาถึงก่อนฆ่าอย่างน้อย 30 นาที ขนสัตว์ป่วยแยกจากสัตว์ปกติ ที่พักรถมีหลังคาและระบายอากาศดี และตรวจสัตว์ปีกก่อนเข้าฆ่า (2) พื้นที่ไม่สะอาด: แขวนขึ้น shackle ผ่านอุปกรณ์รองอก ระยะเวลาจากแขวนถึง stunner ไม่เกิน 20 วินาที ทำให้สลบด้วยไฟฟ้า (ประมาณ 150 V, 100 mA ต่อตัว) เชือดใต้ขากรรไกรล่างให้ตัดหลอดเลือดแดงใหญ่ หลอดเลือดดำใหญ่ หลอดลม และหลอดอาหาร ลวกที่ 58°C ขึ้นไปแล้วถอนขนโดยไม่สัมผัสพื้น แยกหัวและตัดแข้ง เปิดช่องท้องอย่างระวังไม่ให้กระเพาะ ลำไส้ และถุงน้ำดีฉีกขาด จัดเครื่องในให้ตรงกับซาก ตรวจซากและเครื่องในหลังฆ่า แล้วล้างซากด้านนอกและด้านใน (3) พื้นที่สะอาด (หลังล้างครั้งสุดท้าย): ลดอุณหภูมิใจกลางซากและเครื่องในส่วนที่บริโภคได้ให้ไม่เกิน 7°C ภายในประมาณ 1 ชั่วโมง ด้วยน้ำเย็นแบบ counter-flow หรืออากาศเย็น ห้องเย็นพื้นไม่ดูดซับน้ำ ป้องกันหยดน้ำควบแน่นสัมผัสซาก ซากสูงจากพื้นอย่างน้อย 30 cm และไม่สัมผัสผนัง แล้วตัดแต่ง ชั่งน้ำหนัก และแบ่งชั้นคุณภาพตาม มกษ. 6700-2548 (4) บรรจุในภาชนะที่ได้มาตรฐาน ติดฉลาก เก็บและขนส่งโดยควบคุมอุณหภูมิใจกลางเนื้อไม่เกิน 7°C",
    "explain": "เกณฑ์ตัวเลขของสัตว์ปีกต่างจากสุกรและโค เช่น สุกรต้องมาถึงก่อนฆ่าอย่างน้อย 2 ชั่วโมง โคและกระบืออย่างน้อย 4 ชั่วโมง และซากสุกรหรือโคต้องลดอุณหภูมิใจกลางให้ไม่เกิน 7°C ภายใน 24 ชั่วโมง ส่วนซากสัตว์ปีกต้องถึงเกณฑ์นี้ภายในประมาณ 1 ชั่วโมง",
