    "id": 212136,
    "subject": "milk-meat-hygiene",
    "topic": "meat-slaughter",
    "year": 5,
    "type": "short",
    "examScope": "final",
    "q": "จงอธิบาย CCP (critical control point)",
    "keywords": [
      "HACCP หลักการที่ 2",
      "จุดที่ต้องควบคุม",
      "ขจัดหรือลดอันตรายให้อยู่ในระดับที่ยอมรับได้",
      "critical limit",
      "decision tree",
      "monitoring",
      "corrective action"
    ],
    "model_answer": "CCP (critical control point) คือจุดหรือขั้นตอนในกระบวนการผลิตที่ต้องควบคุม เพื่อป้องกัน ขจัด หรือลดอันตรายทางชีวภาพ เคมี หรือกายภาพให้อยู่ในระดับที่ยอมรับได้ ถ้าไม่ควบคุมอันตรายจะถึงผู้บริโภค การระบุ CCP เป็นหลักการที่ 2 ของ HACCP ต่อจากการวิเคราะห์อันตราย ใช้ decision tree ถามทีละข้อ: มีมาตรการควบคุมที่ขั้นตอนนี้หรือไม่ (ถ้าไม่มีแต่จำเป็นต่อความปลอดภัย ต้องปรับขั้นตอนการผลิต), ขั้นตอนนี้ออกแบบมาเพื่อลดอันตรายให้อยู่ในระดับที่ยอมรับได้หรือไม่ (ถ้าใช่ เป็น CCP), การปนเปื้อนมีโอกาสเกินระดับที่ยอมรับได้หรือไม่ (ถ้าไม่ ไม่เป็น CCP) และมีขั้นตอนต่อไปที่กำจัดหรือลดอันตรายได้หรือไม่ (ถ้ามี ไม่เป็น CCP ถ้าไม่มี เป็น CCP) แต่ละ CCP ต้องกำหนด critical limit (เกณฑ์ที่แยกยอมรับได้กับไม่ได้) ระบบเฝ้าระวัง (monitoring) การแก้ไขเมื่อเกินเกณฑ์ (corrective action) การทวนสอบ (verification) และการบันทึกเอกสาร",
    "explain": "ตัวอย่างจากโรงงานนม UHT: CCP1 การรับน้ำนม (critical limit ไม่มียาปฏิชีวนะตกค้าง) CCP2 UHT sterilization (มากกว่า 133°C นานกว่า 4 วินาที) และ CCP3 aseptic filling (บรรจุภัณฑ์ปิดสนิท) ในโรงฆ่าสัตว์ HACCP และ GMP เป็นระบบหลักที่ใช้ควบคุมเชื้อก่อโรค เชื้อที่ทำให้เน่าเสีย และการปนเปื้อนข้าม",
    "source": "5. Standard of milk industry and milk products SJ 2026 หน้า 77-79, 83-86; Meat quality and wholesomeness หน้า 32-33",
