    "id": 212138,
    "subject": "milk-meat-hygiene",
    "topic": "meat-ante-post-mortem",
    "year": 5,
    "type": "short",
    "examScope": "final",
    "q": "จงอธิบายขั้นตอนและหลักการในการทำ antemortem inspection",
    "keywords": [
      "คัดเฉพาะสัตว์สุขภาพดีเข้าฆ่า",
      "บันทึกข้อมูลสัตว์",
      "ตรวจภายใน 24 ชั่วโมงก่อนฆ่า",
      "ดูทั้งสองข้างขณะพักและเคลื่อนไหว",
      "การหายใจ พฤติกรรม ท่าเดิน ท่าทาง",
      "แยก suspect",
      "emergency slaughter",
      "ห้ามฆ่า"
    ],
    "model_answer": "หลักการ: คัดให้เฉพาะสัตว์ที่ดูสุขภาพดีและสรีรวิทยาปกติเข้าฆ่า แยกสัตว์ผิดปกติออก ให้สัตว์ได้พักอย่างเหมาะสมพร้อมข้อมูลทางคลินิก ช่วยวินิจฉัยและตัดสินซาก ลดการปนเปื้อนบนพื้นที่ฆ่าโดยแยกสัตว์สกปรกและคัดสัตว์ป่วยทิ้ง ให้สัตว์บาดเจ็บหรือเจ็บปวดได้รับการฆ่าฉุกเฉินอย่างมีมนุษยธรรม และระบุสัตว์ป่วยที่ได้รับยาปฏิชีวนะ ยาเคมีบำบัด ยาฆ่าแมลง หรือสารกำจัดศัตรูพืช ขั้นตอน: (1) บันทึกข้อมูล ได้แก่ ชื่อเจ้าของ lot เวลามาถึง ชนิด เพศ ประวัติโรคและการจัดการ วันเวลาที่ตรวจ อาการ อุณหภูมิร่างกาย เหตุผลที่กักสัตว์ และลายมือชื่อผู้ตรวจ (2) ตรวจภายใน 24 ชั่วโมงก่อนฆ่า และตรวจซ้ำถ้าเลื่อนการฆ่าเกินหนึ่งวัน ดูสัตว์ทั้งสองข้างขณะพักและขณะเคลื่อนไหว (3) สังเกตความผิดปกติของการหายใจ พฤติกรรม ท่าเดิน ท่าทาง (เช่น downer) โครงสร้างและรูปร่าง (ฝี ข้อบวม ไส้เลื่อน เต้านมอักเสบ lumpy jaw ท้องอืด) สิ่งคัดหลั่งหรือสิ่งที่ยื่นออกจากช่องเปิดของร่างกาย สี และกลิ่น (4) ตัดสิน: สัตว์ปกติผ่านเข้าฆ่า สัตว์ที่มีอาการแยกเป็น suspect และกักไว้ตรวจ สัตว์ที่ฟกช้ำมากหรือกระดูกหักให้ฆ่าฉุกเฉิน และสัตว์ที่เป็นโรคต้องห้าม เช่น FMD, ASF, black quarter, hemorrhagic septicemia ห้ามฆ่า ในสัตว์ปีก ตรวจสภาพทั่วไปในกรงและหลังแขวน shackle ก่อนเชือด และแจ้งสัตวแพทย์เมื่อพบโรคที่ต้องรายงาน เช่น AI และ ND",
    "explain": "ผลการตรวจก่อนฆ่าต้องนำไปใช้ร่วมกับผลการตรวจหลังฆ่าในการตัดสินซากขั้นสุดท้าย",
