    "model_answer": "โรคที่ทำให้ขายเนื้อไม่ได้ ได้แก่ โรคที่ห้ามนำสัตว์เข้าฆ่าหรือต้องทำลายทั้งซากและเครื่องใน เช่น African swine fever และ foot and mouth disease (ห้ามฆ่า ซากและเครื่องในต้องทำลาย) black quarter และ hemorrhagic septicemia (ห้ามฆ่า) anthrax, brucellosis, bovine spongiform encephalopathy และ tuberculosis (ทำลายทั้งซาก) และโรคที่เกณฑ์ของไทยถือว่าสัตว์ที่เป็นหรือสงสัยว่าเป็นโรคนั้นไม่เหมาะสมที่จะใช้เนื้อเป็นอาหาร ซึ่งมี 26 โรค นอกจากโรคข้างต้นส่วนใหญ่แล้วยังมี โรคพิษสุนัขบ้า ไข้หวัดนก ไข้หวัดใหญ่ชนิดเอ salmonellosis, campylobacteriosis, trichinellosis, toxoplasmosis และ cysticercosis",
