    "explain": "การตัดสินตามเกณฑ์การตรวจ: ซากที่ผอมเพราะโรคติดเชื้อเรื้อรังต้องทำลายทั้งซากและเครื่องใน สัตว์ที่บวมน้ำทั้งตัวอาจถูกตัดสินไม่ให้ฆ่าตั้งแต่การตรวจก่อนฆ่า ซากที่มีไข้ร่วมกับมีแบคทีเรียหรือ toxin ในกระแสเลือดต้องทำลาย และในสัตว์ปีก ซากที่ตายด้วยสาเหตุอื่นที่ไม่ใช่การฆ่าต้องทำลาย",
